public class SolutionTest {
    public static void main(String[] args) {
        testNormalCalculationAndSplit();
        testIndependentRounding();
        testAllServiceLevels();
        testBoundaryValues();
        testInvalidArguments();
        testInvalidParticipantIndexes();
        testOverflow();
        testStableResult();
    }

    private static void testNormalCalculationAndSplit() {
        Solution.PaymentSummary result = Solution.calculatePayment(
                10_000L, 825, 1_000, Solution.ServiceLevel.IMPRESSIVE, 3);

        assertEquals(1_000L, result.getDiscountCents(), "discount");
        assertEquals(743L, result.getTaxCents(), "tax");
        assertEquals(1_800L, result.getGratuityCents(), "gratuity");
        assertEquals(11_543L, result.getTotalCents(), "total");
        assertEquals(3, result.getParticipantCount(), "participant count");
        assertEquals(3_848L, result.getShareCents(0), "first share");
        assertEquals(3_848L, result.getShareCents(1), "second share");
        assertEquals(3_847L, result.getShareCents(2), "third share");
    }

    private static void testIndependentRounding() {
        Solution.PaymentSummary result = Solution.calculatePayment(
                101L, 100, 5_000, Solution.ServiceLevel.UNSATISFACTORY, 4);

        assertEquals(51L, result.getDiscountCents(), "half-cent discount rounds upward");
        assertEquals(1L, result.getTaxCents(), "tax independently rounds upward");
        assertEquals(3L, result.getGratuityCents(), "gratuity independently rounds upward");
        assertEquals(54L, result.getTotalCents(), "rounded total");
        assertEquals(14L, result.getShareCents(0), "remainder assigned to first participant");
        assertEquals(14L, result.getShareCents(1), "remainder assigned to second participant");
        assertEquals(13L, result.getShareCents(2), "floor share for third participant");
        assertEquals(13L, result.getShareCents(3), "floor share for fourth participant");

        Solution.PaymentSummary taxHalf = Solution.calculatePayment(
                1L, 5_000, 0, Solution.ServiceLevel.UNSATISFACTORY, 1);
        assertEquals(1L, taxHalf.getTaxCents(), "exact half-cent tax rounds upward");
        assertEquals(0L, taxHalf.getGratuityCents(), "sub-half-cent gratuity rounds down");
        assertEquals(2L, taxHalf.getTotalCents(), "one-cent subtotal plus rounded tax");

        Solution.PaymentSummary discountHalf = Solution.calculatePayment(
                1L, 0, 5_000, Solution.ServiceLevel.OUTSTANDING, 1);
        assertEquals(1L, discountHalf.getDiscountCents(), "exact half-cent discount rounds upward");
        assertEquals(0L, discountHalf.getTotalCents(), "fully discounted one-cent subtotal");
    }

    private static void testAllServiceLevels() {
        Solution.ServiceLevel[] levels = Solution.ServiceLevel.values();
        long[] expectedGratuities = {500L, 1_000L, 1_500L, 2_000L, 2_500L};

        assertEquals(5, levels.length, "service-level count");
        for (int i = 0; i < levels.length; i++) {
            Solution.PaymentSummary result = Solution.calculatePayment(
                    10_000L, 0, 0, levels[i], 1);
            assertEquals(expectedGratuities[i], result.getGratuityCents(),
                    "gratuity for " + levels[i]);
            assertEquals(10_000L + expectedGratuities[i], result.getTotalCents(),
                    "total for " + levels[i]);
        }
    }

    private static void testBoundaryValues() {
        Solution.PaymentSummary zero = Solution.calculatePayment(
                0L, 10_000, 10_000, Solution.ServiceLevel.OUTSTANDING, 1);
        assertEquals(0L, zero.getDiscountCents(), "zero discount");
        assertEquals(0L, zero.getTaxCents(), "zero tax");
        assertEquals(0L, zero.getGratuityCents(), "zero gratuity");
        assertEquals(0L, zero.getTotalCents(), "zero total");
        assertEquals(0L, zero.getShareCents(0), "zero share");

        Solution.PaymentSummary maximumDiscount = Solution.calculatePayment(
                Long.MAX_VALUE, 10_000, 10_000,
                Solution.ServiceLevel.OUTSTANDING, 2);
        assertEquals(Long.MAX_VALUE, maximumDiscount.getDiscountCents(),
                "maximum subtotal can be fully discounted without spurious overflow");
        assertEquals(0L, maximumDiscount.getTaxCents(), "tax on zero discounted subtotal");
        assertEquals(0L, maximumDiscount.getGratuityCents(), "gratuity on zero discounted subtotal");
        assertEquals(0L, maximumDiscount.getTotalCents(), "fully discounted maximum subtotal");

        Solution.PaymentSummary manyParticipants = Solution.calculatePayment(
                1L, 0, 0, Solution.ServiceLevel.UNSATISFACTORY, Integer.MAX_VALUE);
        assertEquals(Integer.MAX_VALUE, manyParticipants.getParticipantCount(),
                "maximum participant count");
        assertEquals(1L, manyParticipants.getShareCents(0), "first participant receives remainder");
        assertEquals(0L, manyParticipants.getShareCents(1), "second participant receives floor share");
        assertEquals(0L, manyParticipants.getShareCents(Integer.MAX_VALUE - 1),
                "last participant receives floor share");
    }

    private static void testInvalidArguments() {
        expectThrows(IllegalArgumentException.class,
                () -> Solution.calculatePayment(-1L, 0, 0,
                        Solution.ServiceLevel.OKAY, 1), "negative subtotal");
        expectThrows(IllegalArgumentException.class,
                () -> Solution.calculatePayment(1L, -1, 0,
                        Solution.ServiceLevel.OKAY, 1), "negative tax rate");
        expectThrows(IllegalArgumentException.class,
                () -> Solution.calculatePayment(1L, 10_001, 0,
                        Solution.ServiceLevel.OKAY, 1), "tax rate above maximum");
        expectThrows(IllegalArgumentException.class,
                () -> Solution.calculatePayment(1L, 0, -1,
                        Solution.ServiceLevel.OKAY, 1), "negative discount rate");
        expectThrows(IllegalArgumentException.class,
                () -> Solution.calculatePayment(1L, 0, 10_001,
                        Solution.ServiceLevel.OKAY, 1), "discount rate above maximum");
        expectThrows(IllegalArgumentException.class,
                () -> Solution.calculatePayment(1L, 0, 0, null, 1),
                "null service level");
        expectThrows(IllegalArgumentException.class,
                () -> Solution.calculatePayment(1L, 0, 0,
                        Solution.ServiceLevel.OKAY, 0), "zero participants");
        expectThrows(IllegalArgumentException.class,
                () -> Solution.calculatePayment(1L, 0, 0,
                        Solution.ServiceLevel.OKAY, -1), "negative participants");
    }

    private static void testInvalidParticipantIndexes() {
        Solution.PaymentSummary result = Solution.calculatePayment(
                100L, 0, 0, Solution.ServiceLevel.OKAY, 2);
        expectThrows(IndexOutOfBoundsException.class,
                () -> result.getShareCents(-1), "negative participant index");
        expectThrows(IndexOutOfBoundsException.class,
                () -> result.getShareCents(2), "index equal to participant count");
        expectThrows(IndexOutOfBoundsException.class,
                () -> result.getShareCents(Integer.MAX_VALUE), "very large participant index");
    }

    private static void testOverflow() {
        expectThrows(ArithmeticException.class,
                () -> Solution.calculatePayment(Long.MAX_VALUE, 0, 0,
                        Solution.ServiceLevel.UNSATISFACTORY, 1),
                "overflow while adding gratuity to subtotal");
        expectThrows(ArithmeticException.class,
                () -> Solution.calculatePayment(Long.MAX_VALUE, 10_000, 0,
                        Solution.ServiceLevel.OKAY, 1),
                "overflow while adding full-rate tax");
    }

    private static void testStableResult() {
        Solution.PaymentSummary result = Solution.calculatePayment(
                999L, 333, 777, Solution.ServiceLevel.SOLID, 7);
        long discount = result.getDiscountCents();
        long tax = result.getTaxCents();
        long gratuity = result.getGratuityCents();
        long total = result.getTotalCents();
        long[] shares = new long[result.getParticipantCount()];
        for (int i = 0; i < shares.length; i++) {
            shares[i] = result.getShareCents(i);
        }

        assertEquals(discount, result.getDiscountCents(), "stable discount");
        assertEquals(tax, result.getTaxCents(), "stable tax");
        assertEquals(gratuity, result.getGratuityCents(), "stable gratuity");
        assertEquals(total, result.getTotalCents(), "stable total");

        long shareSum = 0L;
        for (int i = 0; i < shares.length; i++) {
            assertEquals(shares[i], result.getShareCents(i), "stable share " + i);
            shareSum += shares[i];
            if (i > 0) {
                assertTrue(shares[i - 1] >= shares[i], "extra cents must go to earlier participants");
                assertTrue(shares[i - 1] - shares[i] <= 1L, "shares differ by at most one cent");
            }
        }
        assertEquals(total, shareSum, "shares sum to total");
    }

    private interface ThrowingAction {
        void run();
    }

    private static void expectThrows(Class<? extends Throwable> expected,
                                     ThrowingAction action,
                                     String label) {
        try {
            action.run();
        } catch (Throwable actual) {
            if (expected.isInstance(actual)) {
                return;
            }
            throw new AssertionError(label + ": expected " + expected.getName()
                    + " but got " + actual.getClass().getName(), actual);
        }
        throw new AssertionError(label + ": expected " + expected.getName());
    }

    private static void assertEquals(long expected, long actual, String label) {
        if (expected != actual) {
            throw new AssertionError(label + ": expected " + expected + " but got " + actual);
        }
    }

    private static void assertTrue(boolean condition, String label) {
        if (!condition) {
            throw new AssertionError(label);
        }
    }
}

