import java.util.Arrays;
import java.util.List;

public class SolutionTest {
    public static void main(String[] args) {
        testValidNoticeAndNormalization();
        testOrderDuplicatesCommentsAndCdata();
        testNumericBoundaries();
        testRequiredStructure();
        testInvalidValues();
        testMalformedAndEmptyInput();
        testDoctypeAndEntitiesAreRejected();
        testMessagesAreUnmodifiableAndStable();
    }

    private static void testValidNoticeAndNormalization() {
        String xml = "<?xml version=\"1.0\"?>"
                + "<Notice>"
                + "<Number> 42 </Number>"
                + "<Category>  Maintenance Alert  </Category>"
                + "<Messages>"
                + "<Message> First message </Message>"
                + "<Message>Second message</Message>"
                + "</Messages>"
                + "</Notice>";

        Solution.Notice notice = Solution.parseNotice(xml);
        assertEquals(42, notice.getNumber(), "number");
        assertEquals("Maintenance Alert", notice.getCategory(), "trimmed category");
        assertListEquals(Arrays.asList("First message", "Second message"),
                notice.getMessages(), "trimmed messages");
    }

    private static void testOrderDuplicatesCommentsAndCdata() {
        String xml = "<Notice>"
                + "<!-- <Number>999</Number><Message>fake</Message> -->"
                + "<Messages>"
                + "<!-- ignored -->"
                + "<Message>same</Message>"
                + "<Message><![CDATA[ same ]]></Message>"
                + "<Message>last</Message>"
                + "</Messages>"
                + "<Category><![CDATA[ category ]]></Category>"
                + "<Number>7</Number>"
                + "</Notice>";

        Solution.Notice notice = Solution.parseNotice(xml);
        assertEquals(7, notice.getNumber(), "number with reordered direct children");
        assertEquals("category", notice.getCategory(), "CDATA category normalization");
        assertListEquals(Arrays.asList("same", "same", "last"),
                notice.getMessages(), "message order and duplicates");
    }

    private static void testNumericBoundaries() {
        Solution.Notice zero = Solution.parseNotice(
                "<Notice><Number>000</Number><Category>C</Category>"
                        + "<Messages><Message>M</Message></Messages></Notice>");
        assertEquals(0, zero.getNumber(), "zero with leading zeroes");

        Solution.Notice maximum = Solution.parseNotice(
                "<Notice><Number>2147483647</Number><Category>C</Category>"
                        + "<Messages><Message>M</Message></Messages></Notice>");
        assertEquals(Integer.MAX_VALUE, maximum.getNumber(), "maximum integer");
    }

    private static void testRequiredStructure() {
        expectIllegalArgument("wrong root",
                "<Other><Number>1</Number><Category>C</Category>"
                        + "<Messages><Message>M</Message></Messages></Other>");
        expectIllegalArgument("missing number",
                "<Notice><Category>C</Category>"
                        + "<Messages><Message>M</Message></Messages></Notice>");
        expectIllegalArgument("missing category",
                "<Notice><Number>1</Number>"
                        + "<Messages><Message>M</Message></Messages></Notice>");
        expectIllegalArgument("missing messages",
                "<Notice><Number>1</Number><Category>C</Category></Notice>");
        expectIllegalArgument("duplicate number",
                "<Notice><Number>1</Number><Number>2</Number><Category>C</Category>"
                        + "<Messages><Message>M</Message></Messages></Notice>");
        expectIllegalArgument("duplicate category",
                "<Notice><Number>1</Number><Category>C</Category><Category>D</Category>"
                        + "<Messages><Message>M</Message></Messages></Notice>");
        expectIllegalArgument("duplicate messages container",
                "<Notice><Number>1</Number><Category>C</Category>"
                        + "<Messages><Message>A</Message></Messages>"
                        + "<Messages><Message>B</Message></Messages></Notice>");
        expectIllegalArgument("unexpected direct element",
                "<Notice><Number>1</Number><Category>C</Category><Extra/>"
                        + "<Messages><Message>M</Message></Messages></Notice>");
        expectIllegalArgument("nested number cannot substitute for direct number",
                "<Notice><Wrapper><Number>1</Number></Wrapper><Category>C</Category>"
                        + "<Messages><Message>M</Message></Messages></Notice>");
        expectIllegalArgument("no message children",
                "<Notice><Number>1</Number><Category>C</Category><Messages/></Notice>");
        expectIllegalArgument("unexpected child in messages",
                "<Notice><Number>1</Number><Category>C</Category>"
                        + "<Messages><Message>M</Message><Other>X</Other></Messages></Notice>");
        expectIllegalArgument("nested message cannot substitute for direct message",
                "<Notice><Number>1</Number><Category>C</Category>"
                        + "<Messages><Wrapper><Message>M</Message></Wrapper></Messages></Notice>");
        expectIllegalArgument("comment cannot supply number",
                "<Notice><!-- <Number>1</Number> --><Category>C</Category>"
                        + "<Messages><Message>M</Message></Messages></Notice>");
        expectIllegalArgument("comment cannot supply message",
                "<Notice><Number>1</Number><Category>C</Category>"
                        + "<Messages><!-- <Message>M</Message> --></Messages></Notice>");
    }

    private static void testInvalidValues() {
        expectIllegalArgument("negative number",
                "<Notice><Number>-1</Number><Category>C</Category>"
                        + "<Messages><Message>M</Message></Messages></Notice>");
        expectIllegalArgument("numeric overflow",
                "<Notice><Number>2147483648</Number><Category>C</Category>"
                        + "<Messages><Message>M</Message></Messages></Notice>");
        expectIllegalArgument("nondecimal number",
                "<Notice><Number>12x</Number><Category>C</Category>"
                        + "<Messages><Message>M</Message></Messages></Notice>");
        expectIllegalArgument("empty number",
                "<Notice><Number> </Number><Category>C</Category>"
                        + "<Messages><Message>M</Message></Messages></Notice>");
        expectIllegalArgument("empty category",
                "<Notice><Number>1</Number><Category>   </Category>"
                        + "<Messages><Message>M</Message></Messages></Notice>");
        expectIllegalArgument("Unicode-blank category",
                "<Notice><Number>1</Number><Category> \u2003 </Category>"
                        + "<Messages><Message>M</Message></Messages></Notice>");
        expectIllegalArgument("empty message",
                "<Notice><Number>1</Number><Category>C</Category>"
                        + "<Messages><Message>   </Message></Messages></Notice>");
        expectIllegalArgument("Unicode-blank message",
                "<Notice><Number>1</Number><Category>C</Category>"
                        + "<Messages><Message> \u2003 </Message></Messages></Notice>");
    }

    private static void testMalformedAndEmptyInput() {
        expectIllegalArgument("empty string", "");
        expectIllegalArgument("whitespace-only string", " \n\t ");
        expectIllegalArgument("unclosed document",
                "<Notice><Number>1</Number><Category>C</Category>"
                        + "<Messages><Message>M</Message></Messages>");
        expectIllegalArgument("mismatched tags",
                "<Notice><Number>1</Category><Category>C</Category>"
                        + "<Messages><Message>M</Message></Messages></Notice>");
        expectIllegalArgument("multiple roots",
                "<Notice><Number>1</Number><Category>C</Category>"
                        + "<Messages><Message>M</Message></Messages></Notice><Notice/>");
    }

    private static void testDoctypeAndEntitiesAreRejected() {
        expectIllegalArgument("internal entity and DOCTYPE",
                "<!DOCTYPE Notice [<!ENTITY value \"secret\">]>"
                        + "<Notice><Number>1</Number><Category>&value;</Category>"
                        + "<Messages><Message>M</Message></Messages></Notice>");

        expectIllegalArgument("external file entity and DOCTYPE",
                "<!DOCTYPE Notice [<!ENTITY value SYSTEM \"file:///definitely-not-present/secret.txt\">]>"
                        + "<Notice><Number>1</Number><Category>C</Category>"
                        + "<Messages><Message>&value;</Message></Messages></Notice>");

        expectIllegalArgument("external network entity and DOCTYPE",
                "<!DOCTYPE Notice [<!ENTITY value SYSTEM \"http://127.0.0.1:9/secret\">]>"
                        + "<Notice><Number>1</Number><Category>C</Category>"
                        + "<Messages><Message>&value;</Message></Messages></Notice>");

        expectIllegalArgument("DOCTYPE without entities",
                "<!DOCTYPE Notice>"
                        + "<Notice><Number>1</Number><Category>C</Category>"
                        + "<Messages><Message>M</Message></Messages></Notice>");
    }

    private static void testMessagesAreUnmodifiableAndStable() {
        Solution.Notice notice = Solution.parseNotice(
                "<Notice><Number>9</Number><Category>C</Category>"
                        + "<Messages><Message>A</Message><Message>B</Message></Messages></Notice>");
        List<String> messages = notice.getMessages();

        expectThrows(UnsupportedOperationException.class,
                () -> messages.add("C"), "message list add must fail");
        expectThrows(UnsupportedOperationException.class,
                () -> messages.set(0, "changed"), "message list set must fail");
        expectThrows(UnsupportedOperationException.class,
                () -> messages.remove(0), "message list remove must fail");

        assertEquals(9, notice.getNumber(), "stable number");
        assertEquals("C", notice.getCategory(), "stable category");
        assertListEquals(Arrays.asList("A", "B"), notice.getMessages(),
                "messages unchanged after mutation attempts");
    }

    private interface ThrowingAction {
        void run();
    }

    private static void expectIllegalArgument(String label, String xml) {
        try {
            Solution.parseNotice(xml);
        } catch (IllegalArgumentException expected) {
            String message = expected.getMessage();
            if (message == null || message.isEmpty()) {
                throw new AssertionError(label + ": IllegalArgumentException message must be nonempty");
            }
            return;
        } catch (Throwable actual) {
            throw new AssertionError(label + ": expected IllegalArgumentException but got "
                    + actual.getClass().getName(), actual);
        }
        throw new AssertionError(label + ": expected IllegalArgumentException");
    }

    private static void expectThrows(Class<? extends Throwable> expected,
                                     ThrowingAction action,
                                     String label) {
        try {
            action.run();
        } catch (Throwable actual) {
            if (expected.isInstance(actual)) {
                return;
            }
            throw new AssertionError(label + ": expected " + expected.getName()
                    + " but got " + actual.getClass().getName(), actual);
        }
        throw new AssertionError(label + ": expected " + expected.getName());
    }

    private static void assertEquals(int expected, int actual, String label) {
        if (expected != actual) {
            throw new AssertionError(label + ": expected " + expected + " but got " + actual);
        }
    }

    private static void assertEquals(String expected, String actual, String label) {
        if (!expected.equals(actual)) {
            throw new AssertionError(label + ": expected [" + expected + "] but got [" + actual + "]");
        }
    }

    private static void assertListEquals(List<String> expected,
                                         List<String> actual,
                                         String label) {
        if (!expected.equals(actual)) {
            throw new AssertionError(label + ": expected " + expected + " but got " + actual);
        }
    }
}

