Implement an in-memory account directory using only the TypeScript standard library.

Export:

```ts
export interface Account { id: string; displayName: string; active: boolean }
export type AccountListener = (account: Readonly<Account> | undefined) => void;
export class AccountDirectory {
  register(account: Account): Account;
  authenticate(id: string): Account;
  update(id: string, patch: Partial<Pick<Account, "displayName" | "active">>): Account;
  remove(id: string): boolean;
  find(id: string): Account | undefined;
  watch(id: string, listener: AccountListener): () => void;
}
```

IDs must be non-empty after trimming; invalid IDs throw `TypeError`. Store the trimmed ID. Display names must be non-empty after trimming and are stored trimmed. `active` must be a boolean; invalid values throw `TypeError`. Registration throws `Error` for a duplicate ID. Authentication throws `Error` for missing or inactive accounts. Updating a missing account throws `Error`; an empty display name or invalid `active` value throws before mutation. Update reads `displayName` and `active` directly so supported non-enumerable values are honored. An absent or `undefined` patch field leaves its stored value unchanged; any other invalid supplied value rejects atomically. An empty patch is valid and still notifies. Removal returns false and emits nothing when absent; otherwise it removes and notifies with `undefined`. Watchers are called in registration order only for their ID. Notification snapshots registrations, duplicate watches are independent, unsubscribe is idempotent, and subscription changes during notification apply later. Never retain or expose mutable aliases.

Return only the complete source file; do not include Markdown fences or prose.

export interface Account {
  id: string;
  displayName: string;
  active: boolean;
}

export type AccountListener = (account: Readonly<Account> | undefined) => void;

type Entry = { listener: AccountListener; active: boolean };
type AccountPatch = Partial<Pick<Account, "displayName" | "active">>;

function cleanId(id: unknown): string {
  if (typeof id !== "string") throw new TypeError("invalid id");
  const value = id.trim();
  if (!value) throw new TypeError("id must not be empty");
  return value;
}

function cleanName(name: unknown): string {
  if (typeof name !== "string") throw new TypeError("invalid displayName");
  const value = name.trim();
  if (!value) throw new TypeError("displayName must not be empty");
  return value;
}

function cleanActive(active: unknown): boolean {
  if (typeof active !== "boolean") throw new TypeError("active must be boolean");
  return active;
}

export class AccountDirectory {
  private readonly accounts = new Map<string, Account>();
  private readonly watchers = new Map<string, Entry[]>();

  register(account: Account): Account {
    const id = cleanId(account.id);
    const displayName = cleanName(account.displayName);
    const active = cleanActive(account.active);
    if (this.accounts.has(id)) throw new Error("account already exists");
    const stored: Account = { id, displayName, active };
    this.accounts.set(id, stored);
    this.emit(id, stored);
    return { ...stored };
  }

  authenticate(id: string): Account {
    const account = this.accounts.get(cleanId(id));
    if (!account || !account.active) throw new Error("authentication failed");
    return { ...account };
  }

  update(id: string, patch: AccountPatch): Account {
    const key = cleanId(id);
    const old = this.accounts.get(key);
    if (!old) throw new Error("account not found");

    const displayName = patch.displayName === undefined
      ? old.displayName
      : cleanName(patch.displayName);
    const active = patch.active === undefined
      ? old.active
      : cleanActive(patch.active);
    const next: Account = { id: old.id, displayName, active };
    this.accounts.set(key, next);
    this.emit(key, next);
    return { ...next };
  }

  remove(id: string): boolean {
    const key = cleanId(id);
    if (!this.accounts.delete(key)) return false;
    this.emit(key, undefined);
    return true;
  }

  find(id: string): Account | undefined {
    const value = this.accounts.get(cleanId(id));
    return value ? { ...value } : undefined;
  }

  watch(id: string, listener: AccountListener): () => void {
    const key = cleanId(id);
    const entry: Entry = { listener, active: true };
    const entries = this.watchers.get(key) ?? [];
    entries.push(entry);
    this.watchers.set(key, entries);
    return () => {
      entry.active = false;
    };
  }

  private emit(id: string, value: Account | undefined): void {
    const current = (this.watchers.get(id) ?? []).filter((entry) => entry.active);
    for (const entry of current) {
      entry.listener(value ? { ...value } : undefined);
    }
  }
}

