import { Account, AccountDirectory, AccountListener } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function equal<T>(actual: T, expected: T, message: string): void {
  if (actual !== expected) {
    throw new Error(message + ": expected " + String(expected) + ", got " + String(actual));
  }
}

function jsonEqual(actual: unknown, expected: unknown, message: string): void {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a !== e) throw new Error(message + ": expected " + e + ", got " + a);
}

function throwsAs(action: () => void, kind: new (...args: any[]) => Error, message: string): void {
  let caught: unknown;
  try {
    action();
  } catch (error) {
    caught = error;
  }
  assert(caught instanceof kind, message);
}

const directory = new AccountDirectory();
const registrationEvents: string[] = [];
const stopPreRegistrationWatch = directory.watch(" user-1 ", (account) => {
  registrationEvents.push(account === undefined ? "undefined" : account.displayName);
});

const input: Account = { id: "  user-1  ", displayName: "  Alice  ", active: true };
const registered = directory.register(input);
jsonEqual(registered, { id: "user-1", displayName: "Alice", active: true }, "registration trims stored strings");
jsonEqual(input, { id: "  user-1  ", displayName: "  Alice  ", active: true }, "registration does not mutate input");
jsonEqual(registrationEvents, ["Alice"], "registration notifies an existing watcher");

input.id = "changed";
input.displayName = "changed";
input.active = false;
registered.displayName = "corrupted";
registered.active = false;
jsonEqual(directory.find(" user-1 "), { id: "user-1", displayName: "Alice", active: true }, "registration input and result are not retained aliases");

const foundA = directory.find("user-1")!;
const foundB = directory.find("user-1")!;
assert(foundA !== foundB, "find returns fresh objects");
foundA.displayName = "corrupted";
equal(foundB.displayName, "Alice", "find results do not share mutable state");
equal(directory.find("missing"), undefined, "find returns undefined for a missing account");
jsonEqual(directory.authenticate(" user-1 "), { id: "user-1", displayName: "Alice", active: true }, "authentication normalizes lookup ID");

throwsAs(() => directory.register({ id: "user-1", displayName: "Duplicate", active: true }), Error, "duplicate normalized ID is rejected");
throwsAs(() => directory.authenticate("missing"), Error, "missing account cannot authenticate");

const updateEvents: string[] = [];
const stopUpdateWatch = directory.watch("user-1", (account) => {
  updateEvents.push(account === undefined ? "undefined" : account.displayName + ":" + String(account.active));
});
const updatePatch: Partial<Pick<Account, "displayName" | "active">> = { displayName: "  Alicia  " };
const updated = directory.update(" user-1 ", updatePatch);
jsonEqual(updated, { id: "user-1", displayName: "Alicia", active: true }, "update trims display name and preserves absent active");
jsonEqual(updatePatch, { displayName: "  Alicia  " }, "update does not mutate patch");
updated.displayName = "corrupted";
equal(directory.find("user-1")!.displayName, "Alicia", "update result is not a stored alias");

const nonEnumerablePatch: Partial<Pick<Account, "displayName" | "active">> = {};
Object.defineProperty(nonEnumerablePatch, "displayName", { value: "  Ally  ", enumerable: false });
Object.defineProperty(nonEnumerablePatch, "active", { value: false, enumerable: false });
jsonEqual(directory.update("user-1", nonEnumerablePatch), { id: "user-1", displayName: "Ally", active: false }, "non-enumerable supported update fields are honored");
throwsAs(() => directory.authenticate("user-1"), Error, "inactive account cannot authenticate");

directory.update("user-1", { displayName: undefined, active: undefined });
jsonEqual(directory.find("user-1"), { id: "user-1", displayName: "Ally", active: false }, "undefined update fields are ignored");
directory.update("user-1", {});
equal(updateEvents.length, 4, "empty and undefined-only updates still notify");

const beforeAtomicFailure = directory.find("user-1")!;
throwsAs(
  () => directory.update("user-1", { displayName: "Valid", active: "yes" as unknown as boolean }),
  TypeError,
  "invalid active value throws TypeError"
);
jsonEqual(directory.find("user-1"), beforeAtomicFailure, "invalid multi-field update is atomic");
throwsAs(() => directory.update("user-1", { displayName: "   " }), TypeError, "empty trimmed display name is rejected");
jsonEqual(directory.find("user-1"), beforeAtomicFailure, "invalid display name does not mutate account");
throwsAs(() => directory.update("missing", {}), Error, "updating a missing account throws");

const invalidAccounts: Account[] = [
  { id: "", displayName: "Name", active: true },
  { id: "   ", displayName: "Name", active: true },
  { id: "ok", displayName: "", active: true },
  { id: "ok", displayName: "   ", active: true },
  { id: "ok", displayName: "Name", active: "true" as unknown as boolean }
];
for (let i = 0; i < invalidAccounts.length; i += 1) {
  throwsAs(() => new AccountDirectory().register(invalidAccounts[i]), TypeError, "malformed registration is rejected at index " + String(i));
}
throwsAs(() => directory.find("   "), TypeError, "find rejects invalid ID");
throwsAs(() => directory.authenticate(""), TypeError, "authenticate rejects invalid ID");
throwsAs(() => directory.update("   ", {}), TypeError, "update rejects invalid ID");
throwsAs(() => directory.remove(""), TypeError, "remove rejects invalid ID");
throwsAs(() => directory.watch("   ", () => {}), TypeError, "watch rejects invalid ID");

const sequencing = new AccountDirectory();
sequencing.register({ id: "watched", displayName: "Initial", active: true });
const calls: string[] = [];
let stopSecond: () => void = () => {};
let stopThird: () => void = () => {};
const firstListener: AccountListener = (account) => {
  calls.push("first:" + (account === undefined ? "removed" : account.displayName));
  stopSecond();
  if (account !== undefined && account.displayName === "One") {
    stopThird = sequencing.watch("watched", (later) => {
      calls.push("third:" + (later === undefined ? "removed" : later.displayName));
    });
  }
};
sequencing.watch("watched", firstListener);
stopSecond = sequencing.watch("watched", (account) => {
  calls.push("second:" + (account === undefined ? "removed" : account.displayName));
});
sequencing.update("watched", { displayName: "One" });
jsonEqual(calls, ["first:One", "second:One"], "notification uses a registration snapshot");
sequencing.update("watched", { displayName: "Two" });
jsonEqual(calls, ["first:One", "second:One", "first:Two", "third:Two"], "subscription changes apply to later notifications");
stopSecond();
stopSecond();
stopThird();
stopThird();

const duplicateCalls: string[] = [];
const duplicateListener: AccountListener = () => duplicateCalls.push("called");
const stopDuplicateA = sequencing.watch("watched", duplicateListener);
const stopDuplicateB = sequencing.watch("watched", duplicateListener);
sequencing.update("watched", {});
jsonEqual(duplicateCalls, ["called", "called"], "duplicate watches are independent");
stopDuplicateA();
sequencing.update("watched", {});
jsonEqual(duplicateCalls, ["called", "called", "called"], "unsubscribing one duplicate leaves the other active");
stopDuplicateA();
stopDuplicateB();

const aliasDirectory = new AccountDirectory();
aliasDirectory.register({ id: "alias", displayName: "Safe", active: true });
let secondObserved = "";
aliasDirectory.watch("alias", (account) => {
  if (account !== undefined) (account as Account).displayName = "tampered";
});
aliasDirectory.watch("alias", (account) => {
  secondObserved = account === undefined ? "removed" : account.displayName;
});
aliasDirectory.update("alias", {});
equal(secondObserved, "Safe", "one listener cannot corrupt another listener's account snapshot");
