equal(removalDirectory.remove("gone"), false, "removing an absent account returns false");
jsonEqual(removalEvents, ["undefined"], "absent removal emits no notification");

stopPreRegistrationWatch();
stopPreRegistrationWatch();
stopUpdateWatch();
stopUpdateWatch();

