Create an in-memory reservation book with this public API:

```go
type Reservation struct {
    ID    int
    Guest string
    Seats int
}

type Book struct { /* unexported fields */ }

var ErrInvalidCapacity error
var ErrInvalidReservation error
var ErrCapacityExceeded error
var ErrReservationNotFound error
var ErrInvalidLimit error

func NewBook(capacity int) (*Book, error)
func (b *Book) Add(guest string, seats int) (int, error)
func (b *Book) Get(id int) (Reservation, error)
func (b *Book) List(limit int) ([]Reservation, error)
func (b *Book) Cancel(id int) error
```

`NewBook` rejects capacities below 1 with `ErrInvalidCapacity`. `Add` rejects an empty or whitespace-only guest or seats below 1 with `ErrInvalidReservation`. It rejects a reservation that would make the sum of active seats exceed capacity with `ErrCapacityExceeded`. Successful IDs start at 1 and increase monotonically; canceled IDs are never reused.

`Get` and `Cancel` return `ErrReservationNotFound` for non-positive, unknown, or canceled IDs. `List` rejects negative limits with `ErrInvalidLimit`. It returns active reservations in ascending ID order, truncated to `limit`; limit zero returns a non-nil empty slice. Canceling a reservation immediately restores its seats to the available capacity. Failed operations must leave the book unchanged. The zero value of `Book` is not required to be usable.

Return only the complete source file; do not include Markdown fences or prose.

package solution

import (
	"errors"
	"sort"
	"strings"
)

type Reservation struct {
	ID    int
	Guest string
	Seats int
}

type Book struct {
	capacity int
	used     int
	nextID   int
	entries  map[int]Reservation
}

var ErrInvalidCapacity = errors.New("invalid capacity")
var ErrInvalidReservation = errors.New("invalid reservation")
var ErrCapacityExceeded = errors.New("capacity exceeded")
var ErrReservationNotFound = errors.New("reservation not found")
var ErrInvalidLimit = errors.New("invalid limit")

func NewBook(capacity int) (*Book, error) {
	if capacity < 1 {
		return nil, ErrInvalidCapacity
	}
	return &Book{capacity: capacity, nextID: 1, entries: make(map[int]Reservation)}, nil
}

func (b *Book) Add(guest string, seats int) (int, error) {
	if strings.TrimSpace(guest) == "" || seats < 1 {
		return 0, ErrInvalidReservation
	}
	if seats > b.capacity-b.used {
		return 0, ErrCapacityExceeded
	}
	id := b.nextID
	b.nextID++
	b.used += seats
	b.entries[id] = Reservation{ID: id, Guest: guest, Seats: seats}
	return id, nil
}

func (b *Book) Get(id int) (Reservation, error) {
	reservation, ok := b.entries[id]
	if !ok {
		return Reservation{}, ErrReservationNotFound
	}
	return reservation, nil
}

func (b *Book) List(limit int) ([]Reservation, error) {
	if limit < 0 {
		return nil, ErrInvalidLimit
	}
	result := make([]Reservation, 0)
	if limit == 0 {
		return result, nil
	}
	ids := make([]int, 0, len(b.entries))
	for id := range b.entries {
		ids = append(ids, id)
	}
	sort.Ints(ids)
	for _, id := range ids {
		if len(result) == limit {
			break
		}
		result = append(result, b.entries[id])
	}
	return result, nil
}

func (b *Book) Cancel(id int) error {
	reservation, ok := b.entries[id]
	if !ok {
		return ErrReservationNotFound
	}
	delete(b.entries, id)
	b.used -= reservation.Seats
	return nil
}

