package solution

import (
	"reflect"
	"testing"
)

func TestNewBookValidatesCapacity(t *testing.T) {
	for _, capacity := range []int{0, -1, -100} {
		if _, err := NewBook(capacity); err != ErrInvalidCapacity {
			t.Errorf("NewBook(%d) error = %v, want %v", capacity, err, ErrInvalidCapacity)
		}
	}

	book, err := NewBook(1)
	if err != nil {
		t.Fatalf("NewBook(1) returned unexpected error: %v", err)
	}
	if book == nil {
		t.Fatal("NewBook(1) returned nil")
	}
}

func TestBookAddGetAndListInIDOrder(t *testing.T) {
	book, err := NewBook(10)
	if err != nil {
		t.Fatal(err)
	}

	id1, err := book.Add("Alice", 2)
	if err != nil {
		t.Fatalf("Add Alice: %v", err)
	}
	id2, err := book.Add("Bob", 3)
	if err != nil {
		t.Fatalf("Add Bob: %v", err)
	}
	id3, err := book.Add(" Carol ", 1)
	if err != nil {
		t.Fatalf("Add Carol: %v", err)
	}
	if id1 != 1 || id2 != 2 || id3 != 3 {
		t.Fatalf("IDs = %d, %d, %d; want 1, 2, 3", id1, id2, id3)
	}

	got, err := book.Get(id2)
	if err != nil {
		t.Fatalf("Get(%d): %v", id2, err)
	}
	want := Reservation{ID: 2, Guest: "Bob", Seats: 3}
	if got != want {
		t.Fatalf("Get(%d) = %#v, want %#v", id2, got, want)
	}

	wantList := []Reservation{
		{ID: 1, Guest: "Alice", Seats: 2},
		{ID: 2, Guest: "Bob", Seats: 3},
		{ID: 3, Guest: " Carol ", Seats: 1},
	}
	gotList, err := book.List(10)
	if err != nil {
		t.Fatalf("List(10): %v", err)
	}
	if !reflect.DeepEqual(gotList, wantList) {
		t.Fatalf("List(10) = %#v, want %#v", gotList, wantList)
	}

	limited, err := book.List(2)
	if err != nil {
		t.Fatalf("List(2): %v", err)
	}
	if !reflect.DeepEqual(limited, wantList[:2]) {
		t.Fatalf("List(2) = %#v, want %#v", limited, wantList[:2])
	}
}

func TestListReturnsAnIndependentSnapshot(t *testing.T) {
	book, err := NewBook(3)
	if err != nil {
		t.Fatal(err)
	}
	id, err := book.Add("Original", 1)
	if err != nil {
		t.Fatal(err)
	}

	listed, err := book.List(1)
	if err != nil {
		t.Fatal(err)
	}
	listed[0].Guest = "Changed"
	listed[0].Seats = 99

	got, err := book.Get(id)
	if err != nil {
		t.Fatal(err)
	}
	want := Reservation{ID: id, Guest: "Original", Seats: 1}
	if got != want {
		t.Fatalf("mutating List result changed stored reservation: got %#v, want %#v", got, want)
	}
}

func TestBookRejectsInvalidReservationsWithoutMutation(t *testing.T) {
	book, err := NewBook(4)
	if err != nil {
		t.Fatal(err)
	}

	invalid := []struct {
		guest string
		seats int
	}{
		{"", 1},
		{"   \t\n", 1},
		{"\u2003", 1},
		{"Alice", 0},
		{"Alice", -1},
	}
	for _, tc := range invalid {
		if _, err := book.Add(tc.guest, tc.seats); err != ErrInvalidReservation {
			t.Errorf("Add(%q, %d) error = %v, want %v", tc.guest, tc.seats, err, ErrInvalidReservation)
		}
	}

	empty, err := book.List(10)
	if err != nil {
		t.Fatal(err)
	}
	if empty == nil || len(empty) != 0 {
		t.Fatalf("list after invalid additions = %#v, want non-nil empty slice", empty)
	}

	id, err := book.Add("Valid", 4)
	if err != nil {
		t.Fatalf("valid Add: %v", err)
	}
	if id != 1 {
		t.Fatalf("ID after failed additions = %d, want 1", id)
	}
}

func TestCapacityBoundaryFailureAndRestoration(t *testing.T) {
	book, err := NewBook(5)
	if err != nil {
		t.Fatal(err)
	}

	firstID, err := book.Add("First", 3)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := book.Add("Too large", 3); err != ErrCapacityExceeded {
		t.Fatalf("over-capacity Add error = %v, want %v", err, ErrCapacityExceeded)
	}

	before, err := book.List(10)
	if err != nil {
		t.Fatal(err)
	}
	wantBefore := []Reservation{{ID: firstID, Guest: "First", Seats: 3}}
	if !reflect.DeepEqual(before, wantBefore) {
		t.Fatalf("failed Add mutated book: got %#v, want %#v", before, wantBefore)
	}

	secondID, err := book.Add("Fits exactly", 2)
	if err != nil {
		t.Fatalf("boundary Add: %v", err)
	}
	if secondID != 2 {
		t.Fatalf("ID after failed Add = %d, want 2", secondID)
	}
	if _, err := book.Add("No room", 1); err != ErrCapacityExceeded {
		t.Fatalf("Add to full book error = %v, want %v", err, ErrCapacityExceeded)
	}

	if err := book.Cancel(firstID); err != nil {
		t.Fatalf("Cancel(%d): %v", firstID, err)
	}
	thirdID, err := book.Add("Replacement", 3)
	if err != nil {
		t.Fatalf("Add after cancellation: %v", err)
	}
	if thirdID != 3 {
		t.Fatalf("ID after cancellation = %d, want 3", thirdID)
	}

	active, err := book.List(10)
	if err != nil {
		t.Fatal(err)
	}
	wantActive := []Reservation{
		{ID: 2, Guest: "Fits exactly", Seats: 2},
		{ID: 3, Guest: "Replacement", Seats: 3},
	}
	if !reflect.DeepEqual(active, wantActive) {
		t.Fatalf("active reservations = %#v, want %#v", active, wantActive)
	}
}

func TestMaximumIntCapacityAndOverflowBoundary(t *testing.T) {
	maxInt := int(^uint(0) >> 1)
	book, err := NewBook(maxInt)
	if err != nil {
		t.Fatalf("NewBook(maxInt): %v", err)
	}

	firstID, err := book.Add("Large", maxInt-1)
	if err != nil {
		t.Fatalf("Add(maxInt-1): %v", err)
	}
	secondID, err := book.Add("Final seat", 1)
	if err != nil {
		t.Fatalf("Add final seat: %v", err)
	}
	if firstID != 1 || secondID != 2 {
		t.Fatalf("IDs = %d, %d; want 1, 2", firstID, secondID)
	}
	if _, err := book.Add("Overflow", 1); err != ErrCapacityExceeded {
		t.Fatalf("Add beyond max-int capacity error = %v, want %v", err, ErrCapacityExceeded)
	}

	full, err := book.List(2)
	if err != nil {
		t.Fatal(err)
	}
	wantFull := []Reservation{
		{ID: 1, Guest: "Large", Seats: maxInt - 1},
		{ID: 2, Guest: "Final seat", Seats: 1},
	}
	if !reflect.DeepEqual(full, wantFull) {
		t.Fatalf("full book = %#v, want %#v", full, wantFull)
	}

	if err := book.Cancel(firstID); err != nil {
		t.Fatal(err)
	}
	thirdID, err := book.Add("Large replacement", maxInt-1)
	if err != nil {
		t.Fatalf("Add after restoring large capacity: %v", err)
	}
	if thirdID != 3 {
		t.Fatalf("ID after failed Add and cancellation = %d, want 3", thirdID)
	}
}

func TestGetAndCancelNotFoundCases(t *testing.T) {
	book, err := NewBook(3)
	if err != nil {
		t.Fatal(err)
	}
	id, err := book.Add("Guest", 1)
	if err != nil {
		t.Fatal(err)
	}

	for _, missing := range []int{-5, 0, 2, 999} {
		if _, err := book.Get(missing); err != ErrReservationNotFound {
			t.Errorf("Get(%d) error = %v, want %v", missing, err, ErrReservationNotFound)
		}
		if err := book.Cancel(missing); err != ErrReservationNotFound {
			t.Errorf("Cancel(%d) error = %v, want %v", missing, err, ErrReservationNotFound)
		}
	}

	if err := book.Cancel(id); err != nil {
		t.Fatalf("Cancel(%d): %v", id, err)
	}
	if _, err := book.Get(id); err != ErrReservationNotFound {
		t.Fatalf("Get canceled ID error = %v, want %v", err, ErrReservationNotFound)
	}
	if err := book.Cancel(id); err != ErrReservationNotFound {
		t.Fatalf("second Cancel error = %v, want %v", err, ErrReservationNotFound)
	}

	active, err := book.List(10)
	if err != nil {
		t.Fatal(err)
	}
	if active == nil || len(active) != 0 {
		t.Fatalf("active list after cancellation = %#v, want non-nil empty slice", active)
	}
}

func TestListLimitValidationAndZeroLimit(t *testing.T) {
	book, err := NewBook(4)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := book.Add("One", 1); err != nil {
		t.Fatal(err)
	}
	if _, err := book.Add("Two", 1); err != nil {
		t.Fatal(err)
	}

	if _, err := book.List(-1); err != ErrInvalidLimit {
		t.Fatalf("List(-1) error = %v, want %v", err, ErrInvalidLimit)
	}
	all, err := book.List(10)
	if err != nil {
		t.Fatal(err)
	}
	if len(all) != 2 {
		t.Fatalf("invalid List mutated book: got %d reservations, want 2", len(all))
	}

	zero, err := book.List(0)
	if err != nil {
		t.Fatalf("List(0): %v", err)
	}
	if zero == nil || len(zero) != 0 {
		t.Fatalf("List(0) = %#v, want non-nil empty slice", zero)
	}
}

