package solution

import (
	"errors"
	"sync"
)

var (
	ErrInvalidConfig = errors.New("invalid mailbox config")
	ErrInvalidPacket = errors.New("invalid packet")
	ErrMailboxFull   = errors.New("mailbox full")
)

type MailboxConfig struct {
	Capacity        int
	MaxPayloadBytes int
}

type Packet struct {
	Topic   string
	Payload []byte
}

type Mailbox struct {
	mu      sync.Mutex
	config  MailboxConfig
	packets []Packet
}

func NewMailbox(config MailboxConfig) (*Mailbox, error) {
	if config.Capacity <= 0 || config.MaxPayloadBytes <= 0 {
		return nil, ErrInvalidConfig
	}
	return &Mailbox{config: config}, nil
}

func copyPayload(payload []byte) []byte {
	copied := make([]byte, len(payload))
	copy(copied, payload)
	return copied
}

func (m *Mailbox) Enqueue(packet Packet) error {
	if packet.Topic == "" || len(packet.Payload) > m.config.MaxPayloadBytes {
		return ErrInvalidPacket
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	if len(m.packets) == m.config.Capacity {
		return ErrMailboxFull
	}
	m.packets = append(m.packets, Packet{
		Topic:   packet.Topic,
		Payload: copyPayload(packet.Payload),
	})
	return nil
}

func (m *Mailbox) Drain(topic string, limit int) ([]Packet, error) {
	if topic == "" || limit < 0 {
		return nil, ErrInvalidPacket
	}
	result := make([]Packet, 0)
	if limit == 0 {
		return result, nil
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	kept := make([]Packet, 0, len(m.packets))
	for _, packet := range m.packets {
		if packet.Topic == topic && len(result) < limit {
			result = append(result, Packet{
				Topic:   packet.Topic,
				Payload: copyPayload(packet.Payload),
			})
		} else {
			kept = append(kept, packet)
		}
	}
	m.packets = kept
	return result, nil
}

func (m *Mailbox) Count(topic string) int {
	m.mu.Lock()
	defer m.mu.Unlock()
	if topic == "" {
		return len(m.packets)
	}
	count := 0
	for _, packet := range m.packets {
		if packet.Topic == topic {
			count++
		}
	}
	return count
}

