package solution

import (
	"bytes"
	"fmt"
	"sync"
	"sync/atomic"
	"testing"
)

func TestNewMailboxValidatesConfig(t *testing.T) {
	configs := []MailboxConfig{
		{Capacity: 0, MaxPayloadBytes: 1},
		{Capacity: -1, MaxPayloadBytes: 1},
		{Capacity: 1, MaxPayloadBytes: 0},
		{Capacity: 1, MaxPayloadBytes: -1},
		{Capacity: 0, MaxPayloadBytes: 0},
	}
	for _, config := range configs {
		mailbox, err := NewMailbox(config)
		if err != ErrInvalidConfig {
			t.Errorf("NewMailbox(%+v) error = %v, want %v", config, err, ErrInvalidConfig)
		}
		if mailbox != nil {
			t.Errorf("NewMailbox(%+v) returned non-nil mailbox on failure", config)
		}
	}

	mailbox, err := NewMailbox(MailboxConfig{Capacity: 1, MaxPayloadBytes: 1})
	if err != nil {
		t.Fatalf("valid NewMailbox returned error: %v", err)
	}
	if mailbox == nil {
		t.Fatal("valid NewMailbox returned nil")
	}
}

func TestEnqueueValidationCapacityAndPrecedence(t *testing.T) {
	mailbox, err := NewMailbox(MailboxConfig{Capacity: 1, MaxPayloadBytes: 3})
	if err != nil {
		t.Fatal(err)
	}

	invalid := []Packet{
		{Topic: "", Payload: nil},
		{Topic: "", Payload: []byte{1, 2, 3, 4}},
		{Topic: "valid", Payload: []byte{1, 2, 3, 4}},
	}
	for _, packet := range invalid {
		if err := mailbox.Enqueue(packet); err != ErrInvalidPacket {
			t.Errorf("Enqueue(%#v) error = %v, want %v", packet, err, ErrInvalidPacket)
		}
	}
	if got := mailbox.Count(""); got != 0 {
		t.Fatalf("failed enqueues changed count to %d, want 0", got)
	}

	if err := mailbox.Enqueue(Packet{Topic: "full", Payload: []byte{1, 2, 3}}); err != nil {
		t.Fatalf("boundary-size Enqueue: %v", err)
	}
	if err := mailbox.Enqueue(Packet{Topic: "another", Payload: nil}); err != ErrMailboxFull {
		t.Fatalf("valid Enqueue into full mailbox error = %v, want %v", err, ErrMailboxFull)
	}
	if err := mailbox.Enqueue(Packet{Topic: "", Payload: []byte{1, 2, 3, 4}}); err != ErrInvalidPacket {
		t.Fatalf("invalid Enqueue into full mailbox error = %v, want %v", err, ErrInvalidPacket)
	}
	if got := mailbox.Count(""); got != 1 {
		t.Fatalf("failed full-mailbox enqueues changed count to %d, want 1", got)
	}
}

func TestDrainPreservesInsertionOrderAndRemainingPackets(t *testing.T) {
	mailbox, err := NewMailbox(MailboxConfig{Capacity: 8, MaxPayloadBytes: 8})
	if err != nil {
		t.Fatal(err)
	}
	packets := []Packet{
		{Topic: "a", Payload: []byte("a1")},
		{Topic: "b", Payload: []byte("b1")},
		{Topic: "a", Payload: []byte("a2")},
		{Topic: "b", Payload: []byte("b2")},
		{Topic: "a", Payload: []byte("a3")},
	}
	for _, packet := range packets {
		if err := mailbox.Enqueue(packet); err != nil {
			t.Fatalf("Enqueue(%#v): %v", packet, err)
		}
	}

	drained, err := mailbox.Drain("a", 2)
	if err != nil {
		t.Fatalf("Drain(a, 2): %v", err)
	}
	assertPackets(t, drained, []Packet{
		{Topic: "a", Payload: []byte("a1")},
		{Topic: "a", Payload: []byte("a2")},
	})
	if total, a, b := mailbox.Count(""), mailbox.Count("a"), mailbox.Count("b"); total != 3 || a != 1 || b != 2 {
		t.Fatalf("counts after drain: total=%d a=%d b=%d, want 3,1,2", total, a, b)
	}

	remainingA, err := mailbox.Drain("a", 10)
	if err != nil {
		t.Fatal(err)
	}
	assertPackets(t, remainingA, []Packet{{Topic: "a", Payload: []byte("a3")}})

	remainingB, err := mailbox.Drain("b", 10)
	if err != nil {
		t.Fatal(err)
	}
	assertPackets(t, remainingB, []Packet{
		{Topic: "b", Payload: []byte("b1")},
		{Topic: "b", Payload: []byte("b2")},
	})
	if got := mailbox.Count(""); got != 0 {
		t.Fatalf("final total count = %d, want 0", got)
	}
}

func TestDrainValidationZeroAndNoMatchesDoNotMutate(t *testing.T) {
	mailbox, err := NewMailbox(MailboxConfig{Capacity: 3, MaxPayloadBytes: 4})
	if err != nil {
		t.Fatal(err)
	}
	if err := mailbox.Enqueue(Packet{Topic: "x", Payload: []byte("one")}); err != nil {
		t.Fatal(err)
	}
	if err := mailbox.Enqueue(Packet{Topic: "y", Payload: []byte("two")}); err != nil {
		t.Fatal(err)
	}

	for _, tc := range []struct {
		topic string
		limit int
	}{{"", 1}, {"x", -1}, {"", -1}} {
		if _, err := mailbox.Drain(tc.topic, tc.limit); err != ErrInvalidPacket {
			t.Errorf("Drain(%q, %d) error = %v, want %v", tc.topic, tc.limit, err, ErrInvalidPacket)
		}
	}
	if got := mailbox.Count(""); got != 2 {
		t.Fatalf("malformed drains changed total count to %d, want 2", got)
	}

	zero, err := mailbox.Drain("x", 0)
	if err != nil {
		t.Fatalf("Drain(x, 0): %v", err)
	}
	if zero == nil || len(zero) != 0 {
		t.Fatalf("Drain(x, 0) = %#v, want non-nil empty slice", zero)
	}
	if got := mailbox.Count("x"); got != 1 {
		t.Fatalf("zero-limit drain changed x count to %d, want 1", got)
	}

	none, err := mailbox.Drain("missing", 2)
	if err != nil {
		t.Fatalf("Drain(missing, 2): %v", err)
	}
	if none == nil || len(none) != 0 {
		t.Fatalf("no-match drain = %#v, want non-nil empty slice", none)
	}
	if got := mailbox.Count(""); got != 2 {
		t.Fatalf("no-match drain changed total count to %d, want 2", got)
	}
}

func TestCountUsesExactCaseSensitiveTopic(t *testing.T) {
	mailbox, err := NewMailbox(MailboxConfig{Capacity: 5, MaxPayloadBytes: 1})
	if err != nil {
		t.Fatal(err)
	}
	for _, topic := range []string{"News", "news", "News", " "} {
		if err := mailbox.Enqueue(Packet{Topic: topic}); err != nil {
			t.Fatalf("Enqueue topic %q: %v", topic, err)
		}
	}
	if got := mailbox.Count(""); got != 4 {
		t.Errorf("Count(empty) = %d, want total 4", got)
	}
	if got := mailbox.Count("News"); got != 2 {
		t.Errorf("Count(News) = %d, want 2", got)
	}
	if got := mailbox.Count("news"); got != 1 {
		t.Errorf("Count(news) = %d, want 1", got)
	}
	if got := mailbox.Count("NEWS"); got != 0 {
		t.Errorf("Count(NEWS) = %d, want 0", got)
	}
	if got := mailbox.Count(" "); got != 1 {
		t.Errorf("Count(space) = %d, want 1", got)
	}
}

func TestPayloadsAreCopiedOnInputAndOutput(t *testing.T) {
	mailbox, err := NewMailbox(MailboxConfig{Capacity: 4, MaxPayloadBytes: 8})
	if err != nil {
		t.Fatal(err)
	}

	input := []byte("data")
	if err := mailbox.Enqueue(Packet{Topic: "copy", Payload: input}); err != nil {
		t.Fatal(err)
	}
	if err := mailbox.Enqueue(Packet{Topic: "copy", Payload: input}); err != nil {
		t.Fatal(err)
	}
	input[0] = 'X'

	first, err := mailbox.Drain("copy", 1)
	if err != nil {
		t.Fatal(err)
	}
	assertPackets(t, first, []Packet{{Topic: "copy", Payload: []byte("data")}})
	first[0].Payload[0] = 'Y'

	second, err := mailbox.Drain("copy", 1)
	if err != nil {
		t.Fatal(err)
	}
	assertPackets(t, second, []Packet{{Topic: "copy", Payload: []byte("data")}})
}

func TestNilAndEmptyPayloadsDrainAsNonNilEmptySlices(t *testing.T) {
	mailbox, err := NewMailbox(MailboxConfig{Capacity: 2, MaxPayloadBytes: 2})
	if err != nil {
		t.Fatal(err)
	}
	if err := mailbox.Enqueue(Packet{Topic: "empty", Payload: nil}); err != nil {
		t.Fatal(err)
	}
	if err := mailbox.Enqueue(Packet{Topic: "empty", Payload: []byte{}}); err != nil {
		t.Fatal(err)
	}

	got, err := mailbox.Drain("empty", 2)
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 2 {
		t.Fatalf("drained %d packets, want 2", len(got))
	}
	for i, packet := range got {
		if packet.Topic != "empty" {
			t.Errorf("packet %d topic = %q, want %q", i, packet.Topic, "empty")
		}
		if packet.Payload == nil || len(packet.Payload) != 0 {
			t.Errorf("packet %d payload = %#v, want non-nil empty slice", i, packet.Payload)
		}
	}
}

func TestDrainRestoresMailboxCapacity(t *testing.T) {
	mailbox, err := NewMailbox(MailboxConfig{Capacity: 2, MaxPayloadBytes: 1})
	if err != nil {
		t.Fatal(err)
	}
	if err := mailbox.Enqueue(Packet{Topic: "a"}); err != nil {
		t.Fatal(err)
	}
	if err := mailbox.Enqueue(Packet{Topic: "b"}); err != nil {
		t.Fatal(err)
	}
	if _, err := mailbox.Drain("a", 1); err != nil {
		t.Fatal(err)
	}
	if err := mailbox.Enqueue(Packet{Topic: "c"}); err != nil {
		t.Fatalf("Enqueue after drain: %v", err)
	}
	if got := mailbox.Count(""); got != 2 {
		t.Fatalf("total count = %d, want 2", got)
	}
}

func TestMaximumIntLogicalCapacity(t *testing.T) {
	maxInt := int(^uint(0) >> 1)
	mailbox, err := NewMailbox(MailboxConfig{Capacity: maxInt, MaxPayloadBytes: 1})
	if err != nil {
		t.Fatalf("NewMailbox(maxInt capacity): %v", err)
	}

	if err := mailbox.Enqueue(Packet{Topic: "a", Payload: []byte{7}}); err != nil {
		t.Fatalf("first Enqueue: %v", err)
	}
	if err := mailbox.Enqueue(Packet{Topic: "b", Payload: nil}); err != nil {
		t.Fatalf("second Enqueue: %v", err)
	}
	if got := mailbox.Count(""); got != 2 {
		t.Fatalf("total count = %d, want 2", got)
	}

	drained, err := mailbox.Drain("a", 1)
	if err != nil {
		t.Fatal(err)
	}
	assertPackets(t, drained, []Packet{{Topic: "a", Payload: []byte{7}}})

	none, err := mailbox.Drain("missing", 1)
	if err != nil {
		t.Fatal(err)
	}
	if none == nil || len(none) != 0 {
		t.Fatalf("no-match drain = %#v, want non-nil empty slice", none)
	}

	last, err := mailbox.Drain("b", 1)
	if err != nil {
		t.Fatal(err)
	}
	if len(last) != 1 || last[0].Payload == nil || len(last[0].Payload) != 0 {
		t.Fatalf("nil payload drain = %#v, want one packet with non-nil empty payload", last)
	}
	if got := mailbox.Count(""); got != 0 {
		t.Fatalf("final count = %d, want 0", got)
	}
}

func TestMailboxConcurrentOperationsConservePackets(t *testing.T) {
	const (
		enqueueWorkers = 4
		enqueuesEach  = 50
		drainWorkers   = 4
		drainsEach     = 60
		countWorkers   = 2
		countsEach     = 100
	)
	const plannedEnqueues = enqueueWorkers * enqueuesEach

	maxInt := int(^uint(0) >> 1)
	mailbox, err := NewMailbox(MailboxConfig{Capacity: maxInt, MaxPayloadBytes: 1})
	if err != nil {
		t.Fatal(err)
	}

	start := make(chan struct{})
	errCh := make(chan error, plannedEnqueues+drainWorkers*drainsEach)
	var successful int64
	var drained int64
	var invalidCount int32
	var wg sync.WaitGroup

	for worker := 0; worker < enqueueWorkers; worker++ {
		wg.Add(1)
		go func(worker int) {
			defer wg.Done()
			<-start
			for i := 0; i < enqueuesEach; i++ {
				packet := Packet{Topic: "shared", Payload: []byte{byte(worker)}}
				if err := mailbox.Enqueue(packet); err != nil {
					errCh <- fmt.Errorf("enqueue worker %d iteration %d: %w", worker, i, err)
					continue
				}
				atomic.AddInt64(&successful, 1)
			}
		}(worker)
	}

	for worker := 0; worker < drainWorkers; worker++ {
		wg.Add(1)
		go func(worker int) {
			defer wg.Done()
			<-start
			for i := 0; i < drainsEach; i++ {
				packets, err := mailbox.Drain("shared", 1)
				if err != nil {
					errCh <- fmt.Errorf("drain worker %d iteration %d: %w", worker, i, err)
					continue
				}
				atomic.AddInt64(&drained, int64(len(packets)))
			}
		}(worker)
	}

	for worker := 0; worker < countWorkers; worker++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			for i := 0; i < countsEach; i++ {
				count := mailbox.Count("")
				if count < 0 || count > plannedEnqueues {
					atomic.StoreInt32(&invalidCount, 1)
				}
				_ = mailbox.Count("shared")
			}
		}()
	}

	close(start)
	wg.Wait()
	close(errCh)
	for err := range errCh {
		t.Error(err)
	}
	if atomic.LoadInt32(&invalidCount) != 0 {
		t.Error("Count returned a value outside the possible range during concurrent operations")
	}

	successCount := atomic.LoadInt64(&successful)
	drainedCount := atomic.LoadInt64(&drained)
	if drainedCount > successCount {
		t.Fatalf("drained count %d exceeds successful enqueue count %d", drainedCount, successCount)
	}
	remaining := mailbox.Count("")
	if int64(remaining) != successCount-drainedCount {
		t.Fatalf("remaining count = %d, want %d from successful=%d drained=%d", remaining, successCount-drainedCount, successCount, drainedCount)
	}

	final, err := mailbox.Drain("shared", plannedEnqueues)
	if err != nil {
		t.Fatalf("final Drain: %v", err)
	}
	if len(final) != remaining {
		t.Fatalf("final Drain returned %d packets, want %d", len(final), remaining)
	}
	if successCount != drainedCount+int64(len(final)) {
		t.Fatalf("packet conservation failed: successful=%d concurrently drained=%d finally drained=%d", successCount, drainedCount, len(final))
	}
	if got := mailbox.Count(""); got != 0 {
		t.Fatalf("count after final Drain = %d, want 0", got)
	}
}

func assertPackets(t *testing.T, got, want []Packet) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("packet count = %d, want %d; got %#v", len(got), len(want), got)
	}
	for i := range want {
		if got[i].Topic != want[i].Topic || !bytes.Equal(got[i].Payload, want[i].Payload) {
			t.Fatalf("packet %d = %#v, want %#v", i, got[i], want[i])
		}
	}
}

