'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(
  Reflect.ownKeys(api).sort((a, b) => String(a).localeCompare(String(b))),
  ['createRegistry', 'executeCommand', 'searchEntries']
);

const { createRegistry, executeCommand, searchEntries } = api;
assert.strictEqual(typeof createRegistry, 'function');
assert.strictEqual(typeof executeCommand, 'function');
assert.strictEqual(typeof searchEntries, 'function');

const empty = createRegistry();
assert.deepStrictEqual(empty, { entries: [] });
assert.notStrictEqual(createRegistry().entries, empty.entries);

const sourceEntry = Object.freeze({
  key: 'alpha',
  code: 'CODE-1',
  owner: 'Alice',
  openedOn: '2024-01-01'
});
const sourceEntries = Object.freeze([sourceEntry]);
const registry = createRegistry(sourceEntries);
assert.notStrictEqual(registry.entries, sourceEntries);
assert.notStrictEqual(registry.entries[0], sourceEntry);
assert.strictEqual(registry.entries[0].key, 'alpha');
assert.strictEqual(registry.entries[0].code, 'CODE-1');
assert.strictEqual(registry.entries[0].owner, 'Alice');
assert.strictEqual(registry.entries[0].openedOn, '2024-01-01');

const hiddenEntry = {};
Object.defineProperties(hiddenEntry, {
  key: { value: 'hidden', enumerable: false },
  code: { value: 'H-1', enumerable: false },
  owner: { value: 'Hidden Owner', enumerable: false },
  openedOn: { value: '2024-05-05', enumerable: false }
});
const inheritedEntry = Object.create({
  key: 'inherited',
  code: 'I-1',
  owner: 'Inherited Owner',
  openedOn: '2024-06-06'
});
const readable = createRegistry([hiddenEntry, inheritedEntry]);
assert.notStrictEqual(readable.entries[0], hiddenEntry);
assert.notStrictEqual(readable.entries[1], inheritedEntry);
assert.strictEqual(readable.entries[0].key, 'hidden');
assert.strictEqual(readable.entries[0].code, 'H-1');
assert.strictEqual(readable.entries[0].owner, 'Hidden Owner');
assert.strictEqual(readable.entries[0].openedOn, '2024-05-05');
assert.strictEqual(readable.entries[1].key, 'inherited');
assert.strictEqual(readable.entries[1].code, 'I-1');
assert.strictEqual(readable.entries[1].owner, 'Inherited Owner');
assert.strictEqual(readable.entries[1].openedOn, '2024-06-06');

const emptyStrings = createRegistry([
  { key: '', code: '', owner: '', openedOn: '' }
]);
assert.strictEqual(emptyStrings.entries.length, 1);

for (const bad of [null, {}, 'entries', 42, true]) {
  assert.throws(() => createRegistry(bad), TypeError);
}
for (const badEntry of [
  null,
  undefined,
  'entry',
  7,
  {},
  { key: 'k', code: 'c', owner: 'o' },
  { key: 1, code: 'c', owner: 'o', openedOn: 'd' },
  { key: 'k', code: null, owner: 'o', openedOn: 'd' },
  { key: 'k', code: 'c', owner: {}, openedOn: 'd' },
  { key: 'k', code: 'c', owner: 'o', openedOn: false },
  { key: new String('k'), code: 'c', owner: 'o', openedOn: 'd' }
]) {
  assert.throws(() => createRegistry([badEntry]), TypeError);
}
assert.throws(
  () => createRegistry([
    { key: 'same', code: 'a', owner: 'x', openedOn: '1' },
    { key: 'same', code: 'b', owner: 'y', openedOn: '2' }
  ]),
  Error
);

const baseInput = Object.freeze([
  Object.freeze({ key: 'a', code: 'Red-100', owner: 'Alice Smith', openedOn: '2024-01-01' }),
  Object.freeze({ key: 'b', code: 'BLUE-200', owner: 'Bob', openedOn: '2024-02-02' })
]);
const base = createRegistry(baseInput);
const aRef = base.entries[0];
const bRef = base.entries[1];
const baseSnapshot = JSON.parse(JSON.stringify(base));

const addedInput = Object.freeze({
  key: 'c', code: 'Green-300', owner: 'Carol', openedOn: '2024-03-03'
});
const added = executeCommand(base, { type: 'add', entry: addedInput });
assert.notStrictEqual(added, base);
assert.notStrictEqual(added.entries, base.entries);
assert.strictEqual(added.entries[0], aRef);
assert.strictEqual(added.entries[1], bRef);
assert.notStrictEqual(added.entries[2], addedInput);
assert.strictEqual(added.entries[2].key, 'c');
assert.strictEqual(added.entries[2].code, 'Green-300');
assert.strictEqual(added.entries[2].owner, 'Carol');
assert.strictEqual(added.entries[2].openedOn, '2024-03-03');
assert.deepStrictEqual(base, baseSnapshot);

const inheritedAdd = Object.create({
  key: 'd', code: 'Dark-400', owner: 'Dana', openedOn: '2024-04-04'
});
const addedInherited = executeCommand(base, { type: 'add', entry: inheritedAdd });
assert.notStrictEqual(addedInherited.entries[2], inheritedAdd);
assert.strictEqual(addedInherited.entries[2].key, 'd');
assert.strictEqual(addedInherited.entries[2].code, 'Dark-400');
assert.strictEqual(addedInherited.entries[2].owner, 'Dana');
assert.strictEqual(addedInherited.entries[2].openedOn, '2024-04-04');

assert.throws(
  () => executeCommand(base, {
    type: 'add',
    entry: { key: 'a', code: 'duplicate', owner: 'Nobody', openedOn: '2024-04-04' }
  }),
  Error
);
assert.throws(() => executeCommand(base, { type: 'add', entry: { key: 'x' } }), TypeError);
assert.deepStrictEqual(base, baseSnapshot);

const removed = executeCommand(base, { type: 'remove', key: 'a' });
assert.notStrictEqual(removed, base);
assert.notStrictEqual(removed.entries, base.entries);
assert.deepStrictEqual(removed.entries, [bRef]);
assert.strictEqual(removed.entries[0], bRef);
assert.strictEqual(executeCommand(base, { type: 'remove', key: 'missing' }), base);

const changes = Object.freeze({
  code: 'RED-101',
  owner: 'Alicia',
  openedOn: '2025-01-01',
  key: 'b',
  ignored: 99
});
const edited = executeCommand(base, { type: 'edit', key: 'a', changes });
assert.notStrictEqual(edited, base);
assert.notStrictEqual(edited.entries, base.entries);
assert.notStrictEqual(edited.entries[0], aRef);
assert.strictEqual(edited.entries[1], bRef);
assert.strictEqual(edited.entries[0].key, 'a');
assert.strictEqual(edited.entries[0].code, 'RED-101');
assert.strictEqual(edited.entries[0].owner, 'Alicia');
assert.strictEqual(edited.entries[0].openedOn, '2025-01-01');
assert.strictEqual(changes.key, 'b');
assert.strictEqual(changes.ignored, 99);
assert.deepStrictEqual(base, baseSnapshot);

const hiddenChanges = {};
Object.defineProperty(hiddenChanges, 'code', {
  value: 'HIDDEN-UPDATE',
  enumerable: false
});
const hiddenEdited = executeCommand(base, {
  type: 'edit', key: 'a', changes: hiddenChanges
});
assert.strictEqual(hiddenEdited.entries[0].key, 'a');
assert.strictEqual(hiddenEdited.entries[0].code, 'HIDDEN-UPDATE');
assert.strictEqual(hiddenEdited.entries[0].owner, 'Alice Smith');
assert.strictEqual(hiddenEdited.entries[0].openedOn, '2024-01-01');

assert.strictEqual(
  executeCommand(base, { type: 'edit', key: 'missing', changes: null }),
  base
);
assert.strictEqual(
  executeCommand(base, { type: 'edit', key: 'missing', changes: { code: 1 } }),
  base
);

const emptyEdit = executeCommand(base, { type: 'edit', key: 'a', changes: {} });
assert.notStrictEqual(emptyEdit, base);
assert.notStrictEqual(emptyEdit.entries, base.entries);
assert.notStrictEqual(emptyEdit.entries[0], aRef);
assert.strictEqual(emptyEdit.entries[0].key, aRef.key);
assert.strictEqual(emptyEdit.entries[0].code, aRef.code);
assert.strictEqual(emptyEdit.entries[0].owner, aRef.owner);
assert.strictEqual(emptyEdit.entries[0].openedOn, aRef.openedOn);
assert.strictEqual(emptyEdit.entries[1], bRef);

for (const changesValue of [null, undefined, 'x', 4]) {
  assert.throws(
    () => executeCommand(base, { type: 'edit', key: 'a', changes: changesValue }),
    TypeError
  );
}
for (const badChanges of [
  { code: null },
  { owner: 1 },
  { openedOn: false }
]) {
  assert.throws(
    () => executeCommand(base, { type: 'edit', key: 'a', changes: badChanges }),
    TypeError
  );
}

for (const badCommand of [
  null,
  undefined,
  'add',
  3,
  [],
  {},
  { type: 'unknown' },
  { type: 'remove' },
  { type: 'remove', key: 1 },
  { type: 'edit', key: null, changes: {} }
]) {
  assert.throws(() => executeCommand(base, badCommand), TypeError);
}

const all = searchEntries(base, '');
assert.deepStrictEqual(all, base.entries);
assert.notStrictEqual(all, base.entries);
assert.strictEqual(all[0], aRef);
assert.strictEqual(all[1], bRef);

const byCode = searchEntries(base, 'rEd-1');
assert.deepStrictEqual(byCode, [aRef]);
assert.strictEqual(byCode[0], aRef);
const byOwner = searchEntries(base, 'SMITH');
assert.deepStrictEqual(byOwner, [aRef]);
assert.strictEqual(byOwner[0], aRef);
const inheritedSearch = searchEntries(readable, 'owner');
assert.deepStrictEqual(inheritedSearch, readable.entries);
assert.strictEqual(inheritedSearch[0], readable.entries[0]);
assert.strictEqual(inheritedSearch[1], readable.entries[1]);
const noMatches = searchEntries(base, 'not-present');
assert.deepStrictEqual(noMatches, []);
assert.notStrictEqual(noMatches, searchEntries(base, 'not-present'));
for (const badTerm of [undefined, null, 0, false, {}, []]) {
  assert.throws(() => searchEntries(base, badTerm), TypeError);
}
assert.deepStrictEqual(base, baseSnapshot);

