    throw new TypeError('invalid registry');
  }
}

function executeCommand(registry, command) {
  validateRegistry(registry);
  if (command === null || typeof command !== 'object') throw new TypeError('invalid command');

  if (command.type === 'add') {
    const entry = copyValidEntry(command.entry);
    if (registry.entries.some((item) => item.key === entry.key)) throw new Error('duplicate key');
    return { entries: [...registry.entries, entry] };
  }

  if (command.type === 'remove') {
    if (typeof command.key !== 'string') throw new TypeError('invalid key');
    const index = registry.entries.findIndex((item) => item.key === command.key);
    if (index < 0) return registry;
    return { entries: registry.entries.filter((_, i) => i !== index) };
  }

  if (command.type === 'edit') {
    if (typeof command.key !== 'string') throw new TypeError('invalid key');
    const index = registry.entries.findIndex((item) => item.key === command.key);
    if (index < 0) return registry;
    if (command.changes === null || typeof command.changes !== 'object') {
      throw new TypeError('invalid edit');
    }

    const current = registry.entries[index];
    const replacement = {
      ...current,
      key: current.key,
      code: current.code,
      owner: current.owner,
      openedOn: current.openedOn
    };
    for (const field of ['code', 'owner', 'openedOn']) {
      if (Object.prototype.hasOwnProperty.call(command.changes, field)) {
        if (typeof command.changes[field] !== 'string') throw new TypeError('invalid change');
        replacement[field] = command.changes[field];
      }
    }
    const entries = registry.entries.slice();
    entries[index] = replacement;
    return { entries };
  }

  throw new TypeError('unknown command');
}

function searchEntries(registry, term) {
  validateRegistry(registry);
  if (typeof term !== 'string') throw new TypeError('term must be a string');
  const needle = term.toLowerCase();
  return registry.entries.filter((entry) =>
    entry.code.toLowerCase().includes(needle) || entry.owner.toLowerCase().includes(needle)
  );
}

module.exports = { createRegistry, executeCommand, searchEntries };

