'use strict';

const assert = require('node:assert');
const partReducer = require('./solution');

assert.strictEqual(typeof partReducer, 'function');

const initial = partReducer(undefined, undefined);
assert.ok(initial && typeof initial === 'object');
assert.deepStrictEqual(Object.keys(initial).sort(), ['byId', 'order']);
assert.strictEqual(Object.getPrototypeOf(initial.byId), null);
assert.deepStrictEqual(Object.keys(initial.byId), []);
assert.deepStrictEqual(initial.order, []);

for (const missingAction of [undefined, null, false, 0, 'REPLACE_PARTS']) {
  const state = partReducer(undefined, missingAction);
  assert.strictEqual(Object.getPrototypeOf(state.byId), null);
  assert.deepStrictEqual(state.order, []);
}

const sentinelState = { byId: Object.create(null), order: [] };
for (const action of [undefined, null, false, 0, 'x']) {
  assert.strictEqual(partReducer(sentinelState, action), sentinelState);
}
for (const action of [[], {}, { type: 'UNKNOWN' }, { type: '' }, { type: null }]) {
  assert.strictEqual(partReducer(sentinelState, action), sentinelState);
}

const emptyReplacement = partReducer(sentinelState, {
  type: 'REPLACE_PARTS', parts: []
});
assert.notStrictEqual(emptyReplacement, sentinelState);
assert.notStrictEqual(emptyReplacement.byId, sentinelState.byId);
assert.notStrictEqual(emptyReplacement.order, sentinelState.order);
assert.strictEqual(Object.getPrototypeOf(emptyReplacement.byId), null);
assert.deepStrictEqual(emptyReplacement.order, []);

const firstInput = Object.freeze({
  id: 'p1', label: 'Frame', hours: 0, pinned: true
});
const secondInput = Object.freeze({
  id: 'p2', label: '', hours: 2.5
});
const partsInput = Object.freeze([firstInput, secondInput]);
const replaced = partReducer(sentinelState, {
  type: 'REPLACE_PARTS', parts: partsInput
});
assert.notStrictEqual(replaced, sentinelState);
assert.strictEqual(Object.getPrototypeOf(replaced.byId), null);
assert.deepStrictEqual(replaced.order, ['p1', 'p2']);
assert.deepStrictEqual(Object.keys(replaced.byId).sort(), ['p1', 'p2']);
assert.notStrictEqual(replaced.byId.p1, firstInput);
assert.notStrictEqual(replaced.byId.p2, secondInput);
assert.strictEqual(replaced.byId.p1.id, 'p1');
assert.strictEqual(replaced.byId.p1.label, 'Frame');
assert.strictEqual(replaced.byId.p1.hours, 0);
assert.strictEqual(replaced.byId.p1.pinned, false);
assert.strictEqual(replaced.byId.p2.id, 'p2');
assert.strictEqual(replaced.byId.p2.label, '');
assert.strictEqual(replaced.byId.p2.hours, 2.5);
assert.strictEqual(replaced.byId.p2.pinned, false);
assert.strictEqual(firstInput.pinned, true);
assert.strictEqual(Object.prototype.hasOwnProperty.call(secondInput, 'pinned'), false);

const hiddenPart = {};
Object.defineProperties(hiddenPart, {
  id: { value: 'hidden', enumerable: false },
  label: { value: 'Hidden Part', enumerable: false },
  hours: { value: 1.25, enumerable: false }
});
const hiddenReplacement = partReducer(undefined, {
  type: 'REPLACE_PARTS', parts: [hiddenPart]
});
assert.deepStrictEqual(hiddenReplacement.order, ['hidden']);
assert.notStrictEqual(hiddenReplacement.byId.hidden, hiddenPart);
assert.strictEqual(hiddenReplacement.byId.hidden.id, 'hidden');
assert.strictEqual(hiddenReplacement.byId.hidden.label, 'Hidden Part');
assert.strictEqual(hiddenReplacement.byId.hidden.hours, 1.25);
assert.strictEqual(hiddenReplacement.byId.hidden.pinned, false);

const special = partReducer(undefined, {
  type: 'REPLACE_PARTS',
  parts: [
    { id: '__proto__', label: 'Special', hours: -0 },
    { id: 'constructor', label: 'Constructor', hours: Number.MAX_VALUE }
  ]
});
assert.strictEqual(Object.getPrototypeOf(special.byId), null);
assert.deepStrictEqual(special.order, ['__proto__', 'constructor']);
assert.strictEqual(special.byId.__proto__.id, '__proto__');
assert.strictEqual(special.byId.__proto__.label, 'Special');
assert.strictEqual(special.byId.__proto__.pinned, false);
assert.ok(Object.is(special.byId.__proto__.hours, -0));
assert.strictEqual(special.byId.constructor.id, 'constructor');
assert.strictEqual(special.byId.constructor.label, 'Constructor');
assert.strictEqual(special.byId.constructor.hours, Number.MAX_VALUE);
assert.strictEqual(special.byId.constructor.pinned, false);

const invalidReplacementParts = [
  undefined,
  null,
  {},
  'parts',
  [null],
  [3],
  [{}],
  [{ id: '', label: 'x', hours: 1 }],
  [{ id: 1, label: 'x', hours: 1 }],
  [{ id: 'x', label: null, hours: 1 }],
  [{ id: 'x', label: 'x', hours: '1' }],
  [{ id: 'x', label: 'x', hours: -0.01 }],
  [{ id: 'x', label: 'x', hours: NaN }],
  [{ id: 'x', label: 'x', hours: Infinity }],
  [{ id: 'x', label: 'x', hours: -Infinity }],
  [
    { id: 'dup', label: 'one', hours: 1 },
    { id: 'dup', label: 'two', hours: 2 }
  ]
];
const replacedOrderRef = replaced.order;
const replacedByIdRef = replaced.byId;
const replacedP1Ref = replaced.byId.p1;
const replacedP2Ref = replaced.byId.p2;
for (const parts of invalidReplacementParts) {
  assert.throws(
    () => partReducer(replaced, { type: 'REPLACE_PARTS', parts }),
    TypeError
  );
  assert.strictEqual(replaced.order, replacedOrderRef);
  assert.strictEqual(replaced.byId, replacedByIdRef);
  assert.strictEqual(replaced.byId.p1, replacedP1Ref);
  assert.strictEqual(replaced.byId.p2, replacedP2Ref);
}

const orderRef = replaced.order;
const byIdRef = replaced.byId;
const p1Ref = replaced.byId.p1;
const p2Ref = replaced.byId.p2;
const pinned = partReducer(replaced, { type: 'PIN_PART', id: 'p1' });
assert.notStrictEqual(pinned, replaced);
assert.notStrictEqual(pinned.byId, byIdRef);
assert.strictEqual(Object.getPrototypeOf(pinned.byId), null);
assert.strictEqual(pinned.order, orderRef);
assert.notStrictEqual(pinned.byId.p1, p1Ref);
assert.strictEqual(pinned.byId.p2, p2Ref);
assert.strictEqual(pinned.byId.p1.id, 'p1');
assert.strictEqual(pinned.byId.p1.label, 'Frame');
assert.strictEqual(pinned.byId.p1.hours, 0);
assert.strictEqual(pinned.byId.p1.pinned, true);
assert.strictEqual(replaced.byId.p1.pinned, false);

const repinned = partReducer(pinned, { type: 'PIN_PART', id: 'p1' });
assert.notStrictEqual(repinned, pinned);
assert.notStrictEqual(repinned.byId, pinned.byId);
assert.notStrictEqual(repinned.byId.p1, pinned.byId.p1);
assert.strictEqual(repinned.byId.p2, pinned.byId.p2);
assert.strictEqual(repinned.order, pinned.order);
assert.strictEqual(repinned.byId.p1.pinned, true);

const unpinned = partReducer(pinned, { type: 'UNPIN_PART', id: 'p1' });
assert.notStrictEqual(unpinned, pinned);
assert.notStrictEqual(unpinned.byId, pinned.byId);
assert.notStrictEqual(unpinned.byId.p1, pinned.byId.p1);
assert.strictEqual(unpinned.byId.p2, pinned.byId.p2);
assert.strictEqual(unpinned.order, pinned.order);
assert.strictEqual(unpinned.byId.p1.pinned, false);
assert.strictEqual(pinned.byId.p1.pinned, true);

const reunpinned = partReducer(replaced, { type: 'UNPIN_PART', id: 'p2' });
assert.notStrictEqual(reunpinned, replaced);
assert.notStrictEqual(reunpinned.byId, replaced.byId);
assert.notStrictEqual(reunpinned.byId.p2, replaced.byId.p2);
assert.strictEqual(reunpinned.byId.p1, replaced.byId.p1);
assert.strictEqual(reunpinned.order, replaced.order);
assert.strictEqual(reunpinned.byId.p2.pinned, false);

assert.strictEqual(partReducer(replaced, { type: 'PIN_PART', id: 'missing' }), replaced);
assert.strictEqual(partReducer(replaced, { type: 'UNPIN_PART', id: 'missing' }), replaced);

for (const type of ['PIN_PART', 'UNPIN_PART']) {
  for (const id of [undefined, null, '', 0, false, {}, []]) {
    assert.throws(() => partReducer(replaced, { type, id }), TypeError);
  }
}

const engine = Object.freeze({
  id: 'engine', label: 'Engine', hours: 4, pinned: false
});
const wing = Object.freeze({
  id: 'wing', label: 'Wing', hours: 2, pinned: false
});
const externalById = Object.create(null);
Object.defineProperty(externalById, 'engine', {
  value: engine,
  enumerable: false,
  writable: true,
  configurable: true
});
externalById.wing = wing;
const externalOrder = Object.freeze(['engine', 'wing']);
const externalState = { byId: externalById, order: externalOrder };

const externalPinned = partReducer(externalState, {
  type: 'PIN_PART', id: 'wing'
});
assert.notStrictEqual(externalPinned, externalState);
assert.notStrictEqual(externalPinned.byId, externalById);
assert.strictEqual(Object.getPrototypeOf(externalPinned.byId), null);
assert.strictEqual(externalPinned.order, externalOrder);
assert.strictEqual(externalPinned.byId.engine, engine);
assert.notStrictEqual(externalPinned.byId.wing, wing);
assert.strictEqual(externalPinned.byId.wing.id, 'wing');
assert.strictEqual(externalPinned.byId.wing.label, 'Wing');
assert.strictEqual(externalPinned.byId.wing.hours, 2);
assert.strictEqual(externalPinned.byId.wing.pinned, true);
assert.strictEqual(wing.pinned, false);

const externalUnpinned = partReducer(externalPinned, {
  type: 'UNPIN_PART', id: 'wing'
});
assert.notStrictEqual(externalUnpinned, externalPinned);
assert.notStrictEqual(externalUnpinned.byId, externalPinned.byId);
assert.strictEqual(externalUnpinned.byId.engine, engine);
assert.notStrictEqual(externalUnpinned.byId.wing, externalPinned.byId.wing);
assert.strictEqual(externalUnpinned.order, externalOrder);
assert.strictEqual(externalUnpinned.byId.wing.pinned, false);

assert.strictEqual(externalState.byId, externalById);
assert.strictEqual(externalState.byId.engine, engine);
assert.strictEqual(externalState.byId.wing, wing);
assert.strictEqual(externalState.order, externalOrder);
assert.deepStrictEqual(replaced.order, ['p1', 'p2']);
assert.strictEqual(replaced.byId.p1, p1Ref);
assert.strictEqual(replaced.byId.p2, p2Ref);
assert.strictEqual(replaced.byId.p1.pinned, false);
assert.strictEqual(replaced.byId.p2.pinned, false);

