import { ReservationStore } from "./solution";
import type { Performance, Reservation, ReservationDraft } from "./solution";

type MutablePerformance = { -readonly [K in keyof Performance]: Performance[K] };
type MutableReservation = { -readonly [K in keyof Reservation]: Reservation[K] };

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equal<T>(actual: T, expected: T, message: string): void {
  if (actual !== expected) {
    throw new Error(message + ": expected " + String(expected) + ", got " + String(actual));
  }
}

function arrayEqual(actual: readonly string[], expected: readonly string[], message: string): void {
  equal(actual.length, expected.length, message + " length");
  for (let index = 0; index < expected.length; index += 1) {
    equal(actual[index], expected[index], message + " at index " + String(index));
  }
}

function reservationEqual(actual: Reservation, expected: Reservation, message: string): void {
  equal(actual.id, expected.id, message + " id");
  equal(actual.customerId, expected.customerId, message + " customerId");
  equal(actual.performanceId, expected.performanceId, message + " performanceId");
  equal(actual.seat, expected.seat, message + " seat");
}

function throwsAs(action: () => void, kind: new (...args: any[]) => Error, message: string): void {
  let caught: unknown;
  try {
    action();
  } catch (error) {
    caught = error;
  }
  assert(caught instanceof kind, message);
}

function throws(action: () => void, message: string): void {
  let didThrow = false;
  try {
    action();
  } catch {
    didThrow = true;
  }
  assert(didThrow, message);
}

throwsAs(
  () => new ReservationStore([{ id: "", venueId: "v1" }]),
  TypeError,
  "constructor rejects an empty performance ID"
);
throwsAs(
  () => new ReservationStore([{ id: "p1", venueId: "" }]),
  TypeError,
  "constructor rejects an empty venue ID"
);
throwsAs(
  () => new ReservationStore([{ id: "p1", venueId: 7 } as unknown as Performance]),
  TypeError,
  "constructor rejects a non-string performance field"
);
throwsAs(
  () => new ReservationStore([
    { id: "duplicate", venueId: "v1" },
    { id: "duplicate", venueId: "v2" }
  ]),
  TypeError,
  "constructor rejects duplicate performance IDs"
);

const emptyStore = new ReservationStore([]);
equal(emptyStore.get("missing"), null, "an empty store has no reservations");
arrayEqual(emptyStore.byCustomer("c1").map((reservation) => reservation.id), [], "empty store customer query");
arrayEqual(emptyStore.byPerformance("p1").map((reservation) => reservation.id), [], "empty store performance query");
equal(emptyStore.delete("missing"), false, "deleting from an empty store returns false");

const originalPerformances: Performance[] = [
  { id: "p1", venueId: "v1" },
  { id: "p2", venueId: "v2" }
];
const store = new ReservationStore(originalPerformances);
(originalPerformances[0] as MutablePerformance).id = "changed";
(originalPerformances[0] as MutablePerformance).venueId = "changed";
originalPerformances.length = 0;

const firstDraft: ReservationDraft = {
  id: "r1",
  customerId: "c1",
  performanceId: "p1",
  seat: "A1"
};
const first = store.add(firstDraft);
reservationEqual(first, { id: "r1", customerId: "c1", performanceId: "p1", seat: "A1" }, "add returns the reservation");
reservationEqual(firstDraft as Reservation, { id: "r1", customerId: "c1", performanceId: "p1", seat: "A1" }, "add does not mutate its draft");

(first as MutableReservation).customerId = "corrupted";
equal(store.get("r1")!.customerId, "c1", "mutating an add result does not mutate storage");
const fetchedA = store.get("r1")!;
const fetchedB = store.get("r1")!;
assert(fetchedA !== fetchedB, "get returns a fresh object each time");
(fetchedA as MutableReservation).seat = "corrupted";
equal(fetchedB.seat, "A1", "get results do not share mutable state");
equal(store.get("missing"), null, "get returns null for a missing ID");

throws(
  () => store.add({ id: "", customerId: "c1", performanceId: "p1", seat: "A2" }),
  "add rejects an empty explicit ID"
);
throws(
  () => store.add({ customerId: "", performanceId: "p1", seat: "A2" }),
  "add rejects an empty customer ID"
);
throws(
  () => store.add({ customerId: "c1", performanceId: "p1", seat: "" }),
  "add rejects an empty seat"
);
throwsAs(
  () => store.add({ customerId: "c1", performanceId: "unknown", seat: "A2" }),
  RangeError,
  "add rejects an unknown performance"
);
throwsAs(
  () => store.add({ id: "r1", customerId: "c2", performanceId: "p1", seat: "A2" }),
  RangeError,
  "add rejects a duplicate explicit ID"
);
reservationEqual(store.get("r1")!, { id: "r1", customerId: "c1", performanceId: "p1", seat: "A1" }, "failed adds do not change an existing reservation");

const generated = store.add({ customerId: "c1", performanceId: "p2", seat: "B1" });
equal(generated.id, "reservation-1", "the first generated ID is deterministic");
store.add({ id: "reservation-2", customerId: "c2", performanceId: "p1", seat: "A2" });
const skipped = store.add({ customerId: "c2", performanceId: "p2", seat: "B2" });
equal(skipped.id, "reservation-3", "generated IDs skip explicit collisions");

arrayEqual(store.byCustomer("c1").map((reservation) => reservation.id), ["r1", "reservation-1"], "customer query preserves insertion order");
arrayEqual(store.byPerformance("p1").map((reservation) => reservation.id), ["r1", "reservation-2"], "performance query preserves insertion order");
arrayEqual(store.byCustomer("absent").map((reservation) => reservation.id), [], "customer query can be empty");
arrayEqual(store.byPerformance("absent").map((reservation) => reservation.id), [], "performance query can be empty");
const queryA = store.byCustomer("c1");
const queryB = store.byCustomer("c1");
assert(queryA !== queryB && queryA[0] !== queryB[0], "queries return fresh arrays and objects");
(queryA[0] as MutableReservation).seat = "corrupted";
queryA.length = 0;
equal(store.get("r1")!.seat, "A1", "mutating query results does not mutate storage");

const patch: Partial<Omit<ReservationDraft, "id">> = { seat: "A9" };
const updated = store.update("r1", patch)!;
reservationEqual(updated, { id: "r1", customerId: "c1", performanceId: "p1", seat: "A9" }, "update changes a supported field");
equal(patch.seat, "A9", "update does not mutate its patch");
(updated as MutableReservation).seat = "corrupted";
equal(store.get("r1")!.seat, "A9", "an update result is a fresh copy");

const nonEnumerablePatch: Partial<Omit<ReservationDraft, "id">> = {};
Object.defineProperty(nonEnumerablePatch, "customerId", { value: "c3", enumerable: false });
Object.defineProperty(nonEnumerablePatch, "performanceId", { value: "p2", enumerable: false });
Object.defineProperty(nonEnumerablePatch, "seat", { value: "B9", enumerable: false });
const nonEnumerableResult = store.update("r1", nonEnumerablePatch)!;
reservationEqual(
  nonEnumerableResult,
  { id: "r1", customerId: "c3", performanceId: "p2", seat: "B9" },
  "update honors non-enumerable supported fields and retains the ID"
);

const undefinedPatch: Partial<Omit<ReservationDraft, "id">> = {
  customerId: undefined,
  performanceId: undefined,
  seat: undefined
};
reservationEqual(store.update("r1", undefinedPatch)!, nonEnumerableResult, "undefined supported fields leave values unchanged");
reservationEqual(store.update("r1", {})!, nonEnumerableResult, "an empty update is valid");

const extraPatch = {
  id: "replacement",
  ignored: "value",
  seat: "B10"
} as unknown as Partial<Omit<ReservationDraft, "id">>;
const extraResult = store.update("r1", extraPatch)!;
equal(extraResult.id, "r1", "an extra id cannot replace the reservation ID");
equal(extraResult.seat, "B10", "supported fields coexist with ignored extra fields");

const missingPatch: Partial<Omit<ReservationDraft, "id">> = { seat: "X" };
equal(store.update("missing", missingPatch), null, "updating a missing reservation returns null");
equal(missingPatch.seat, "X", "a missing-reservation update does not mutate its patch");

const beforeInvalidUpdate = store.get("r1")!;
throws(
  () => store.update("r1", { customerId: "valid-change", seat: "" }),
  "an invalid supported update value throws"
);
reservationEqual(store.get("r1")!, beforeInvalidUpdate, "an invalid multi-field update is atomic");
throws(
  () => store.update("r1", { seat: 4 } as unknown as Partial<Omit<ReservationDraft, "id">>),
  "a non-string supported update value throws"
);
reservationEqual(store.get("r1")!, beforeInvalidUpdate, "a malformed update does not mutate storage");
throwsAs(
  () => store.update("r1", { performanceId: "unknown" }),
  RangeError,
  "an unknown updated performance throws RangeError"
);
reservationEqual(store.get("r1")!, beforeInvalidUpdate, "an unknown performance update does not mutate storage");

const ignoredOnlyPatch = { id: "replacement", active: true } as unknown as Partial<Omit<ReservationDraft, "id">>;
reservationEqual(store.update("r1", ignoredOnlyPatch)!, beforeInvalidUpdate, "an update containing only extra fields is valid and ignored");

equal(store.delete("reservation-1"), true, "delete removes an existing reservation");
equal(store.get("reservation-1"), null, "a deleted reservation cannot be fetched");
equal(store.delete("reservation-1"), false, "deleting the same reservation twice returns false");
arrayEqual(store.byCustomer("c1").map((reservation) => reservation.id), [], "deleted reservations disappear from customer queries");
arrayEqual(store.byPerformance("p2").map((reservation) => reservation.id), ["r1", "reservation-3"], "deletion preserves the insertion order of remaining results");
equal(store.delete("missing"), false, "deleting a missing reservation returns false");

